@using sv_bd4c7a08d4cd467d98b64d7b1de48dd6.Services

<div class="card h-100 product-card" @onclick="OnCardClicked" role="button" style="cursor: pointer;">
    <div class="bg-secondary bg-opacity-25 d-flex align-items-center justify-content-center"
         style="height: 180px;" role="img" aria-label="@Product.Name">
        <span class="text-muted">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h6 class="card-title">@Product.Name</h6>
        <p class="card-text fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <p class="card-text mb-2">
            <span class="text-warning" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">@GetStarRating(Product.Rating)</span>
        </p>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <div class="mt-auto">
            <button class="btn btn-sm btn-success w-100"
                    disabled="@(!Product.InStock)"
                    @onclick="OnAddToCartClicked"
                    @onclick:stopPropagation="true">
                Add to Cart
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductClicked { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private static string GetStarRating(double rating)
    {
        int filled = (int)Math.Round(rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }

    private async Task OnCardClicked()
    {
        await OnProductClicked.InvokeAsync(Product);
    }

    private async Task OnAddToCartClicked()
    {
        await OnAddToCart.InvokeAsync(Product);
    }
}

